using UnityEngine;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Match;
namespace Alterverse.AI
{
[RequireComponent(typeof(Health),typeof(MobaBotBrain),typeof(BotLanePlan),typeof(BotTargetSensor))]public sealed class MobaBotMover:MonoBehaviour
{
[SerializeField]private float fallbackMoveSpeed=3.35f,laneStopDistance=.45f,chaseLimit=8.5f,turnSpeed=9f;private const float ArenaHalfWidth=41f,ArenaHalfHeight=35f;private Health health;private MobaBotBrain brain;private BotLanePlan lanePlan;private BotTargetSensor sensor;private HeroCombatProfile profile;private PlanetBuffReceiver planetBuff;private float nextObjectiveScan;private DimensionPlanet objective;
private float MoveSpeed=>(profile!=null?profile.MoveSpeed:fallbackMoveSpeed)*(planetBuff!=null?planetBuff.MoveSpeedMultiplier:1f);private float CombatStop=>profile!=null?Mathf.Max(1.2f,profile.AttackRange*.82f):1.5f;private void Awake(){health=GetComponent<Health>();brain=GetComponent<MobaBotBrain>();lanePlan=GetComponent<BotLanePlan>();sensor=GetComponent<BotTargetSensor>();profile=GetComponent<HeroCombatProfile>();planetBuff=GetComponent<PlanetBuffReceiver>();}
private void Update(){if(health==null||health.IsDead||brain==null||lanePlan==null)return;if(planetBuff==null)planetBuff=GetComponent<PlanetBuffReceiver>();ScanObjective();Vector3 destination=lanePlan.GetDestination(brain.State);float stopDistance=laneStopDistance;if(brain.State==MobaBotBrain.BotState.Fight&&sensor!=null){Health target=sensor.CurrentTarget;if(target!=null&&!target.IsDead){Vector3 d=target.transform.position-transform.position;d.y=0;if(d.sqrMagnitude<=chaseLimit*chaseLimit){destination=target.transform.position;stopDistance=CombatStop;}}}else if(objective!=null&&objective.Available&&ShouldRotate()){destination=objective.transform.position;stopDistance=2.6f;}MoveToward(destination,stopDistance);}
private void ScanObjective(){if(Time.time<nextObjectiveScan)return;nextObjectiveScan=Time.time+1;objective=null;float best=float.MaxValue;foreach(DimensionPlanet p in FindObjectsByType<DimensionPlanet>(FindObjectsSortMode.None)){if(!p.Available)continue;float d=(p.transform.position-transform.position).sqrMagnitude;if(d<best){best=d;objective=p;}}}private bool ShouldRotate(){if(objective==null)return false;float d=(objective.transform.position-transform.position).sqrMagnitude;if(d>30f*30f)return false;int slot=Mathf.Abs(gameObject.name.GetHashCode())%5;return slot<3||d<13f*13f;}
private void MoveToward(Vector3 destination,float stopDistance){Vector3 delta=destination-transform.position;delta.y=0;if(delta.sqrMagnitude<=stopDistance*stopDistance)return;Vector3 direction=delta.normalized;Vector3 next=transform.position+direction*MoveSpeed*Time.deltaTime;next.x=Mathf.Clamp(next.x,-ArenaHalfWidth,ArenaHalfWidth);next.z=Mathf.Clamp(next.z,-ArenaHalfHeight,ArenaHalfHeight);transform.position=next;if(direction.sqrMagnitude>.01f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(direction),turnSpeed*Time.deltaTime);}
}
}
